import{_ as a,o as r,c as l,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Североевропейская социальная цивилизация","description":"","frontmatter":{},"headers":[],"relativePath":"ru/32-北欧福利型文明.md","filePath":"ru/32-北欧福利型文明.md","lastUpdated":1789183869000}'),o={name:"ru/32-北欧福利型文明.md"};function e(n,t,d,h,s,u){return r(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="североевропеиская-социальная-цивилизация" tabindex="-1">Североевропейская социальная цивилизация <a class="header-anchor" href="#североевропеиская-социальная-цивилизация" aria-label="Permalink to &quot;Североевропейская социальная цивилизация&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>32</td></tr><tr><td>Модуль</td><td>Типы цивилизаций и социальные системы</td></tr><tr><td>Ключевые слова</td><td>Североевропейский социальный, Высокие налоги, Высокое равенство, Всеобщая защита, Индекс счастья</td></tr></tbody></table><h2 id="i-происхождение-и-ядро-идеи" tabindex="-1">I. Происхождение и ядро идей <a class="header-anchor" href="#i-происхождение-и-ядро-идеи" aria-label="Permalink to &quot;I. Происхождение и ядро идей&quot;">​</a></h2><p>Североевропейская социальная — самый эгалитарный из пяти типов; истоки — в моделях Северной Европы реального мира (Швеция, Норвегия, Дания, Финляндия, Исландия). Долгим развитием сложилась «северная модель»: высокие налоги, высокая социальная защита, высокое равенство; баланс экономики и справедливости; первые строки индексов счастья. После основания Симбиотической Цивилизации Якоря модель соединилась с идеями симбиоза — родился тип.</p><p>Ядро — девять иероглифов: «высокая защита, высокое равенство, высокое счастье». Подробно:</p><ol><li><strong>Высокая защита</strong>: государство даёт каждому гражданину «от колыбели до могилы»: образование, медицина, жильё, пенсия, пособия — достойная жизнь</li><li><strong>Высокое равенство</strong>: налоги и трансферты сжимают разрыв богатства; у культиваторов разрыв уровней и ресурсов в разумных пределах</li><li><strong>Высокое счастье</strong>: удовлетворённость, психическое здоровье, доверие в обществе</li></ol><p>Совместимо с «Путь для Каждого»: защита — право эволюции; равенство — дух «прогресса Десяти Тысяч Рас»; счастье — цель.</p><h2 id="ii-социальная-структура" tabindex="-1">II. Социальная структура <a class="header-anchor" href="#ii-социальная-структура" aria-label="Permalink to &quot;II. Социальная структура&quot;">​</a></h2><p>«Государство защиты + плоское общество + сильное гражданское общество»:</p><table tabindex="0"><thead><tr><th>Элемент</th><th>Характеристика</th><th>Функция</th></tr></thead><tbody><tr><td>Государство защиты</td><td>Полная ответственность, налоги — высокая доля ВВП</td><td>Услуги и защита всем</td></tr><tr><td>Плоское общество</td><td>Малые разрывы, слабая иерархия</td><td>Меньше конфликтов, сплочённость</td></tr><tr><td>Сильное гражданское общество</td><td>НКО, союзы, кооперативы</td><td>Дополнение услуг, права, участие</td></tr><tr><td>Культура доверия</td><td>Доверие людям и власти</td><td>Низкие издержки, эффективность</td></tr></tbody></table><h3 id="_2-1-государство-защиты" tabindex="-1">2.1 Государство защиты <a class="header-anchor" href="#_2-1-государство-защиты" aria-label="Permalink to &quot;2.1 Государство защиты&quot;">​</a></h3><p>Типичное «государство всеобщего благосостояния»: налоги (энергия, ресурсы, доход) на всю защиту:</p><ul><li><strong>Образование</strong>: от начального до высшего — бесплатно</li><li><strong>Медицина</strong>: лечение, травмы культивации — бесплатно</li><li><strong>Жильё</strong>: достойное жильё каждому</li><li><strong>Пенсия</strong>: достаточное обеспечение</li><li><strong>Безработица</strong>: базовая защита</li></ul><p>Ядро — «всеобщность»: не помощь бедным, а право всех; каждый — равная защита.</p><h3 id="_2-2-плоское-общество" tabindex="-1">2.2 Плоское общество <a class="header-anchor" href="#_2-2-плоское-общество" aria-label="Permalink to &quot;2.2 Плоское общество&quot;">​</a></h3><p>Малые разрывы, слабая иерархия:</p><ul><li>Разрыв ресурсов старших и младших — в разумных пределах</li><li>Нет привилегий у сильных</li><li>Равное уважительное общение</li><li>Статус — характер и вклад, не высота уровня</li></ul><p>Меньше конфликтов, спокойное развитие по своему ритму.</p><h3 id="_2-3-сильное-гражданское-общество" tabindex="-1">2.3 Сильное гражданское общество <a class="header-anchor" href="#_2-3-сильное-гражданское-общество" aria-label="Permalink to &quot;2.3 Сильное гражданское общество&quot;">​</a></h3><ul><li><strong>Союзы</strong>: представляют культиваторов в переговорах</li><li><strong>Кооперативы</strong>: совместная эксплуатация и доход</li><li><strong>Клубы интересов</strong>: обмен и сотрудничество</li><li><strong>Благотворительность</strong>: помощь слабым</li></ul><p>Дополнение государства: каналы участия, самоконтроль общества.</p><h2 id="iii-модель-культивации" tabindex="-1">III. Модель культивации <a class="header-anchor" href="#iii-модель-культивации" aria-label="Permalink to &quot;III. Модель культивации&quot;">​</a></h2><p>«Всеобщность, индивидуальность, низкое давление»:</p><h3 id="_3-1-всеобщая-защита" tabindex="-1">3.1 Всеобщая защита <a class="header-anchor" href="#_3-1-всеобщая-защита" aria-label="Permalink to &quot;3.1 Всеобщая защита&quot;">​</a></h3><p>Каждому: методы и учебники, энергия, наставничество, объекты — бесплатно. Без экономического давления — «Путь для Каждого».</p><h3 id="_3-2-индивидуальная-поддержка" tabindex="-1">3.2 Индивидуальная поддержка <a class="header-anchor" href="#_3-2-индивидуальная-поддержка" aria-label="Permalink to &quot;3.2 Индивидуальная поддержка&quot;">​</a></h3><p>Оценка и советы каждому; план по особенностям и целям. Не «тысяча войск на одной доске», а разнообразие; выбор по интересам.</p><h3 id="_3-3-низкое-давление" tabindex="-1">3.3 Низкое давление <a class="header-anchor" href="#_3-3-низкое-давление" aria-label="Permalink to &quot;3.3 Низкое давление&quot;">​</a></h3><ul><li>Нет жёсткого отсева</li><li>Оценка — поощрение, не фильтр</li><li>Отдых и досуг; не «затвор для горькой культивации»</li><li>Уровень — не единственный критерий</li></ul><p>Хороший настрой, удовольствие от процесса.</p><h3 id="_3-4-баланс-труда-и-культивации" tabindex="-1">3.4 Баланс труда и культивации <a class="header-anchor" href="#_3-4-баланс-труда-и-культивации" aria-label="Permalink to &quot;3.4 Баланс труда и культивации&quot;">​</a></h3><p>Не всё время культивации; работа, семья, хобби. «Всесторонне развитый человек», не «машина культивации».</p><h2 id="iv-подряд-связанныи-с-результатом" tabindex="-1">IV. Подряд, связанный с результатом <a class="header-anchor" href="#iv-подряд-связанныи-с-результатом" aria-label="Permalink to &quot;IV. Подряд, связанный с результатом&quot;">​</a></h2><p>«Высокозащитный подряд»:</p><ol><li><strong>Высокая база</strong>: выше норматив гарантийных полей</li><li><strong>Высокий избыток в общее</strong>: доля избытка — в общий фонд</li><li><strong>Мягкий стимул</strong>: разрыв невелик</li><li><strong>Ориентация защиты</strong>: приоритет — гарантии</li></ol><p>Плюс: равенство и счастье; минус риска — «подкармливание лени»; разумный стимул.</p><h2 id="v-преимущества-и-вызовы" tabindex="-1">V. Преимущества и вызовы <a class="header-anchor" href="#v-преимущества-и-вызовы" aria-label="Permalink to &quot;V. Преимущества и вызовы&quot;">​</a></h2><h3 id="_5-1-преимущества" tabindex="-1">5.1 Преимущества <a class="header-anchor" href="#_5-1-преимущества" aria-label="Permalink to &quot;5.1 Преимущества&quot;">​</a></h3><ul><li><strong>Счастье</strong>: удовлетворённость высока</li><li><strong>Равенство</strong>: малые разрывы</li><li><strong>Стабильность</strong>: долгий порядок</li><li><strong>Доверие</strong>: эффективность</li></ul><h3 id="_5-2-вызовы" tabindex="-1">5.2 Вызовы <a class="header-anchor" href="#_5-2-вызовы" aria-label="Permalink to &quot;5.2 Вызовы&quot;">​</a></h3><ul><li><strong>Слабая инновация</strong>: защита и низкое давление</li><li><strong>Налоги</strong>: тяжесть для сильных</li><li><strong>Эффективность</strong>: равенство против эффективности</li><li><strong>Демография</strong>: старение — устойчивость фондов</li></ul><p>Ответ: вбирает лучшее — эффективность восточноазиатского, стимулы североамериканского.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Самый эгалитарный тип: «высокая защита, высокое равенство, высокое счастье»; государство защиты, плоское общество, гражданское общество; всеобщая индивидуальная культивация; высокозащитный подряд. Сохраняя своё, ищет баланс защиты и эффективности.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (Обзор пяти типов симбиотических цивилизаций)</li><li>38-共生医疗体系 (Симбиотическая медицинская система)</li><li>39-住房与环境保障 (Жильё и защита окружающей среды)</li></ul>',46)])])}const _=a(o,[["render",e]]);export{p as __pageData,_ as default};
